class Solution {
public:
    Node* copyRandomList(Node* head) {
        if (!head) return nullptr;

        // 1️⃣ Interleave copied nodes with original nodes
        for (Node* cur = head; cur; cur = cur->next->next) {
            Node* copy = new Node(cur->val);
            copy->next = cur->next;
            cur->next = copy;
        }

        // 2️⃣ Assign random pointers for the copies
        for (Node* cur = head; cur; cur = cur->next->next) {
            if (cur->random)
                cur->next->random = cur->random->next;
        }

        // 3️⃣ Separate the two lists
        Node* dummy = new Node(0);          // temporary head for the copied list
        Node* copyIter = dummy;
        for (Node* cur = head; cur; ) {
            Node* copy = cur->next;
            Node* nextOrig = copy->next;    // next original node

            // attach copy to the new list
            copyIter->next = copy;
            copyIter = copy;

            // restore original list's next pointer
            cur->next = nextOrig;
            cur = nextOrig;
        }

        Node* copiedHead = dummy->next;
        delete dummy;                       // clean up helper node
        return copiedHead;
    }
};
